    # Discover the container graph without using the Python call stack.
    nodes = {}
    parents = {}
    pending = [value]
    while pending:
        current = pending.pop()
        kind = _no_log_container_kind(current)
        if kind is None or id(current) in nodes:
            continue
        children = list(current.values()) if kind == 'mapping' else list(current)
