    def transformed(child):
        if id(child) in affected:
            return results[id(child)]
        return child if keys_only else _mask_no_log_string(child, pattern)

    # Immutable containers are assembled from the inside out. Mutable
    # containers already have shells, so cycles through them are supported.
    state = {}
    order = []
    for node_id in affected:
        if node_id in results or node_id in state:
            continue
        stack = [(node_id, False)]
        while stack:
