def _no_log_container_kind(value):
    if isinstance(value, Mapping):
        return 'mapping'
    if isinstance(value, (text_type, binary_type, UserString, memoryview)):
        return None
    if isinstance(value, ItemsView):
        return 'itemsview'
    if isinstance(value, KeysView):
        return 'keysview'
    if isinstance(value, ValuesView):
        return 'valuesview'
    if isinstance(value, Sequence):
        return 'sequence'
    if isinstance(value, Set):
        return 'set'
    return None


def _no_log_pattern(no_log_strings):
    # Longest matches take precedence, independent of the iterable's order.
    strings = frozenset(to_native(s, errors='surrogate_or_strict') for s in no_log_strings)
    strings = frozenset(s for s in strings if s)
    if not strings:
        return strings, None
    ordered = sorted(strings, key=lambda s: (-len(s), s))
    return strings, re.compile('|'.join(re.escape(s) for s in ordered))


def _mask_no_log_string(value, pattern):
    if pattern is None or not isinstance(value, (text_type, binary_type, UserString)):
        return value
    native_value = to_native(value, errors='surrogate_or_strict')
    if not pattern.search(native_value):
        return value
    masked = pattern.sub('********', native_value)
    if isinstance(value, binary_type) and PY3:
        masked = to_bytes(masked, errors='surrogate_or_strict')
    elif isinstance(value, text_type) and PY2:
        masked = to_text(masked, errors='surrogate_or_strict')
    if type(masked) is type(value):
        return masked
    if isinstance(value, text_type):
        rebuilt = text_type.__new__(type(value), masked)
    elif isinstance(value, binary_type):
        rebuilt = binary_type.__new__(type(value), masked)
    else:
        rebuilt = type(value)(masked)
    if isinstance(value, (text_type, binary_type)) and hasattr(value, '__dict__') and hasattr(rebuilt, '__dict__'):
        rebuilt.__dict__.update(value.__dict__)
    return rebuilt


def _empty_no_log_container(value, kind):
    if isinstance(value, defaultdict):
        return type(value)(value.default_factory)
    if isinstance(value, deque):
        return type(value)(maxlen=value.maxlen)
    try:
        return type(value)()
    except TypeError:
        return type(value)({} if kind == 'mapping' else ())


def _immutable_no_log_container(value, kind, elements):
    if kind == 'itemsview':
        return dict(elements).items()
    if kind == 'keysview':
        return dict.fromkeys(elements).keys()
    if kind == 'valuesview':
        return dict(enumerate(elements)).values()
    if kind == 'mapping':
        pairs = list(elements)
        try:
            return type(value)(pairs)
        except TypeError:
            return type(value)(dict(pairs))
    if kind == 'set':
        return type(value)(elements)
    if isinstance(value, tuple) and hasattr(type(value), '_fields'):
        return type(value)(*elements)
    if hasattr(value, 'start') and hasattr(value, 'stop') and hasattr(value, 'step'):
        return type(value)(value.start, value.stop, value.step)
    return type(value)(elements)


